using System;
using System.IO;
using System.Linq;
using LogicLegends.Trees;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using Object=UnityEngine.Object;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveTreePolish
    {
        const string Folder=ArchiveTopicSetup.Folder,Prefabs=Folder+"/Art/Prefabs/",Kit=Prefabs+"Archive_T10_Tree_of_Connections.prefab";
        static Mesh cube,octagon,ring,seed;static TMP_FontAsset font;static Material stone,wood,gold,labels,green;
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Polish T10 Tree of Connections")]
        public static string Apply(){
            if(EditorApplication.isPlayingOrWillChangePlaymode||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new InvalidOperationException("Use stopped Play Mode and a saved scene.");AuditSolo();var primitive=GameObject.CreatePrimitive(PrimitiveType.Cube);cube=primitive.GetComponent<MeshFilter>().sharedMesh;Object.DestroyImmediate(primitive);octagon=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_BeveledOctagon.asset");ring=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_InlayRing.asset");seed=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_RuleCrystal.asset");font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");stone=Mat("Archive_Topic_Stone");wood=Mat("Archive_Topic_Wood");gold=Mat("Archive_Topic_BrassInlay");labels=Mat("Archive_Topic_WorldLabels");green=ColorMat("Archive_T10_LivingEnergy",ArchiveTreePresentation.Green);
            var node=Node();var branch=Branch();var number=Number();var kit=PrefabUtility.LoadPrefabContents(Kit);
            try{var before=kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson).ToArray();foreach(var old in kit.transform.Cast<Transform>().Where(t=>new[]{"T10_Visual_Identity","Mathematical_Inlay","Seal_Inlay"}.Contains(t.name)).ToArray())Object.DestroyImmediate(old.gameObject);var root=new GameObject("T10_Visual_Identity").transform;root.SetParent(kit.transform,false);var inscription=Text(root,"Tree_Entry_Inscription","SELECT PARENT   →   SELECT CHILD   →   CONNECT",new Vector3(0,.09f,7),new Vector2(8.5f,.55f),3);inscription.transform.localRotation=Quaternion.Euler(90,180,0);inscription.color=new Color(.05f,.28f,.33f);
                var art=kit.GetComponent<ArchiveTreePresentation>();if(art==null)art=kit.AddComponent<ArchiveTreePresentation>();art.nodePrefab=node;art.branchPrefab=branch;art.numberPrefab=number;art.nodeCircle=AssetDatabase.LoadAllAssetsAtPath("Assets/Assets/Interface_Sprites/gameplay_interface/joystick_circle_handle.png").OfType<Sprite>().First();art.arrowMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Art/Meshes/Archive_T8_DirectedArrow.asset");art.energyMaterial=green;art.sparkMesh=seed;art.sparkMaterial=Mat("Archive_T1_Sparks");art.selectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Ice_Arrow_Cast_01.wav");art.connectSound=art.selectSound;art.removeSound=art.selectSound;art.correctSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Graph/Correct.wav");art.incorrectSound=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Assets/Sounds Effects/Small Sound Kit/Magic/Mgc_Electric_Hit_01.wav");art.progressMarks=new Renderer[5];for(int i=0;i<5;i++){float x=(2-i)*.65f;Part(root,"Tree_Progress_Brass_"+i,octagon,gold,new Vector3(x,.07f,6.4f),new Vector3(.48f,.07f,.48f));art.progressMarks[i]=Part(root,"Tree_Progress_Seed_"+i,octagon,green,new Vector3(x,.12f,6.4f),new Vector3(.33f,.025f,.33f)).GetComponent<Renderer>();}
                var station=kit.GetComponent<ArchiveTopicStation>();station.title.text="T10  TREES\nTree of Connections";station.board.text="THE TREE OF CONNECTIONS\nGrow and repair the shared branches.\nRead the Book to begin.";station.GetComponentInChildren<ArchiveAnimatedBook>().bookRig.localScale=Vector3.one*.75f;if(!before.SequenceEqual(kit.GetComponentsInChildren<Collider>(true).Select(EditorJsonUtility.ToJson)))throw new InvalidOperationException("T10 collision changed.");PrefabUtility.SaveAsPrefabAsset(kit,Kit);
            }finally{PrefabUtility.UnloadPrefabContents(kit);}return "Saved T10 living-tree kit and three reusable props. Existing Book collider, island and monster access preserved.";
        }
        public static string AuditSolo(){var preview=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Trees.unity");TreeChallengeCatalog source=null;float seconds=0;int managers=0;
            try{var found=preview.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<TreeStageManager>(true)).ToArray();managers=found.Length;if(managers!=1)throw new InvalidOperationException("Expected one current solo TreeStageManager.");var data=new SerializedObject(found[0]);source=data.FindProperty("catalog").objectReferenceValue as TreeChallengeCatalog;seconds=data.FindProperty("countdownSeconds").floatValue;}finally{EditorSceneManager.ClosePreviewScene(preview);}var archive=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(Folder+"/Archive_Topic_Catalog.asset");bool same=source==archive.trees;var result=new{passed=same&&seconds==600&&source!=null&&source.variantSets.Count==5&&source.variantSets.All(g=>g.variants.Count==10),sourceScene="Assets/Scenes/Trees.unity",controller="TreeStageManager",startingSeconds=seconds,incorrectPenaltySeconds=10,sharedOriginalCatalog=same,sourceCatalog=AssetDatabase.GetAssetPath(source),groups=source.variantSets.Select(g=>new{type=g.variants[0].type.ToString(),variants=g.variants.Count}).ToArray(),adaptations=new[]{"Existing shared session and per-actor pending endpoints","Solo validator and parent/root/cycle/removal rules reused","No modal camera or movement lock while reading in the multiplayer arena","Ten-minute remaining clock pauses only at solved Book gates","Wrong work retained; timeout retry keeps solved team progress","Ground-level open branch network; no new collision or navigation blockers"}};Directory.CreateDirectory(Folder+"/Testing/Reports");File.WriteAllText(Folder+"/Testing/Reports/T10SoloAudit.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));if(!result.passed)throw new InvalidOperationException("Current Trees solo configuration differs from expected.");return "Audited the current Trees scene and all fifty original variants.";
        }
        static GameObject Node(){var root=new GameObject("Archive_T10_LivingNode");Part(root.transform,"Anchor_Stone",octagon,stone,new Vector3(0,.04f,0),new Vector3(1.25f,.20f,1.25f));Part(root.transform,"Node_Inlay",ring,green,new Vector3(0,.15f,0),Vector3.one*1.08f);Part(root.transform,"Root_Stem",cube,wood,new Vector3(0,.30f,0),new Vector3(.24f,.38f,.24f));Part(root.transform,"Root_Cap",octagon,gold,new Vector3(0,.49f,0),new Vector3(.42f,.08f,.42f));var pivot=new GameObject("Seed_Pivot").transform;pivot.SetParent(root.transform,false);pivot.localPosition=Vector3.up*.64f;Part(pivot,"Seed",seed,green,Vector3.zero,Vector3.one*.34f);Text(root.transform,"Node_Label","A",new Vector3(0,1.15f,0),new Vector2(1.6f,.72f),3.5f);return Save(root,"Archive_T10_LivingNode.prefab");}
        static GameObject Branch(){var root=new GameObject("Archive_T10_BranchConduit");Part(root.transform,"Root_Branch",cube,wood,new Vector3(0,.055f,0),new Vector3(.22f,.10f,1));Part(root.transform,"Branch_Inlay",cube,green,new Vector3(0,.12f,0),new Vector3(.055f,.015f,1));return Save(root,"Archive_T10_BranchConduit.prefab");}
        static GameObject Number(){var root=new GameObject("Archive_T10_NumberSeal");Part(root.transform,"Number_Stone",octagon,stone,new Vector3(0,.04f,0),new Vector3(1,.20f,1));Part(root.transform,"Choice_Inlay",ring,green,new Vector3(0,.15f,0),Vector3.one*.86f);Text(root.transform,"Number_Label","0",new Vector3(0,.7f,0),new Vector2(.8f,.6f),4);return Save(root,"Archive_T10_NumberSeal.prefab");}
        static GameObject Save(GameObject root,string file){var asset=PrefabUtility.SaveAsPrefabAsset(root,Prefabs+file);Object.DestroyImmediate(root);return asset;}
        static Material Mat(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Folder+"/Art/Materials/"+name+".mat");
        static Material ColorMat(string name,Color c){var m=Mat(name);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Unlit")){name=name,enableInstancing=true};AssetDatabase.CreateAsset(m,Folder+"/Art/Materials/"+name+".mat");}m.SetColor("_BaseColor",c);EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
        static TMP_Text Text(Transform parent,string name,string value,Vector3 pos,Vector2 size,float fontSize){var t=new GameObject(name).AddComponent<TextMeshPro>();t.transform.SetParent(parent,false);t.transform.localPosition=pos;t.rectTransform.sizeDelta=size;t.font=font;t.fontSharedMaterial=labels;t.text=value;t.fontSize=fontSize;t.enableAutoSizing=true;t.fontSizeMax=fontSize;t.fontSizeMin=fontSize-1;t.textWrappingMode=TextWrappingModes.NoWrap;t.richText=false;t.alignment=TextAlignmentOptions.Center;t.color=new Color(1,.94f,.79f);t.raycastTarget=false;return t;}
        static Transform Part(Transform parent,string name,Mesh mesh,Material material,Vector3 pos,Vector3 scale){var p=new GameObject(name,typeof(MeshFilter),typeof(MeshRenderer)).transform;p.SetParent(parent,false);p.localPosition=pos;p.localScale=scale;p.GetComponent<MeshFilter>().sharedMesh=mesh;p.GetComponent<MeshRenderer>().sharedMaterial=material;p.GetComponent<MeshRenderer>().shadowCastingMode=ShadowCastingMode.Off;return p;}
    }
